import{_ as e,o as t,c as o,a5 as r}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 49 话 性能度量与 Web Vitals","description":"","frontmatter":{},"headers":[],"relativePath":"comics/perf/EP.49-web-vitals.md","filePath":"comics/perf/EP.49-web-vitals.md","lastUpdated":1793421609000}'),l={name:"comics/perf/EP.49-web-vitals.md"};function s(i,a,h,n,d,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="漫画-·-第-49-话-性能度量与-web-vitals" tabindex="-1">漫画 · 第 49 话 性能度量与 Web Vitals <a class="header-anchor" href="#漫画-·-第-49-话-性能度量与-web-vitals" aria-label="Permalink to &quot;漫画 · 第 49 话 性能度量与 Web Vitals&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/perf/01-web-vitals">docs/perf/01-web-vitals.md</a> ｜ 原画：<a href="./EP.49-web-vitals.svg">EP.49-web-vitals.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。自信页面&quot;看着挺快&quot;，一上仪表盘三座全部亮红，才发现体感和指标是两回事。</li><li><strong>标签君</strong>：结构师，负责把 PerformanceObserver 采集、p75 聚合、预算看板这条链路摆清楚。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱改完一版页面，拍胸脯说&quot;顺滑得很&quot;。标签君默默打开生产环境的 RUM 看板：LCP 4.8s、INP 620ms、CLS 0.34，三座仪表全红。更扎心的是同一个人刷新三次，三个数字都不重样。标签君说：性能不是感觉，是分布——先学会量，再谈优化。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>三座仪表分别对应 Web Vitals 的核心三指标：LCP 衡量最大内容块出现的时刻，4.8s 意味着首屏主视觉迟迟不出现；INP 衡量每次交互到下一帧绘制的延迟，620ms 让点击像按在棉花上；CLS 衡量布局偏移，0.34 说明图片、广告位在加载中反复&quot;跳&quot;。三者共同点：都只能在真实设备、真实网络下才有意义，本地开发机上常常一片绿。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>度量链路分三步：① 用 <code>PerformanceObserver</code> 订阅 <code>largest-contentful-paint</code>、<code>event</code>（或 <code>first-input</code>）、<code>layout-shift</code> 等条目，并带 <code>buffered: true</code> 补收早于脚本执行的记录；② 把原始条目按页面、设备、网络分桶，取 <strong>p75</strong>（第 75 百分位）而不是平均值，避免少量极慢用户被平均掉；③ 把 p75 与阈值（LCP ≤ 2.5s、INP ≤ 200ms、CLS ≤ 0.1）对照，落到预算看板。注意 Lab（Lighthouse）可复现、可进 CI，Field（RUM）才是真实用户，二者互补。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>看板把&quot;实测 ÷ 预算&quot;归一成柱长：LCP 2.1s / 2.5s 达标，INP 340ms / 200ms 越线变红，CLS 0.08 / 0.1 达标。右侧是 CI 门禁：PR 构建跑 Lighthouse，超预算阻断合并；线上 p75 越线触发告警。一格只盯三指标，异常再下钻到页面与设备分桶——先有可报警的数字，才有资格谈优化。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>三指标阈值记牢：LCP ≤ 2.5s、INP ≤ 200ms、CLS ≤ 0.1，统一看 p75。</li><li>Lab 与 Field 互补：Lighthouse 管可复现与 CI，RUM 管真实用户分布。</li><li>聚合看 p75 不看均值，均值会被少数极慢用户或极快缓存用户骗过去。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：团队用平均 LCP 汇报，数字一直 1.8s 很漂亮，但客服仍收到&quot;打开很慢&quot;的投诉，问题可能出在哪？</p><p><strong>答</strong>：平均值被大量缓存命中、网络好的用户拉低了。少数弱网、低端机用户可能 LCP 超过 5s，但在均值里只占很小权重。应该按 p75（甚至 p90）分设备、分网络聚合，并检查是否有地区或机型长尾；均值只适合看整体趋势，不适合做达标判断。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>用 PerformanceObserver 采集 LCP/INP/CLS 并本地打印 p75：<a href="./../../examples/perf/01-web-vitals">examples/perf/01-web-vitals</a></li><li>对照实验：同一页面在 Fast 3G 与无节流下的指标差异，观察分布而非单点。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>指标有了，下一步是让首屏真的快起来。第 50 话《首屏加载与白屏治理》——巨包 JS、阻塞 CSS、字体 FOIT 三连击，看关键渲染路径怎么被抢修。</p>',22)])])}const b=e(l,[["render",s]]);export{p as __pageData,b as default};
